The following patch would fix it but it requires incref and decref on object's dictionary so it add a bit of reference counting overhead:
```diff
diff --git a/Objects/dictobject.c b/Objects/dictobject.c
index ac4a46dab10..e26979dd0b6 100644
--- a/Objects/dictobject.c
+++ b/Objects/dictobject.c
@@ -6985,7 +6985,10 @@ _PyObject_StoreInstanceAttribute(PyObject *obj, PyObject *name, PyObject *value)
             Py_DECREF(dict);
             return res;
         }
-        return store_instance_attr_dict(obj, dict, name, value);
+        Py_INCREF(dict);
+        int res = store_instance_attr_dict(obj, dict, name, value);
+        Py_DECREF(dict);
+        return res;
     }

 #ifdef Py_GIL_DISABLED
@@ -7014,7 +7017,10 @@ _PyObject_StoreInstanceAttribute(PyObject *obj, PyObject *name, PyObject *value)
             return res;
         }
     }
-    return store_instance_attr_dict(obj, dict, name, value);
+    Py_INCREF(dict);
+    int res = store_instance_attr_dict(obj, dict, name, value);
+    Py_DECREF(dict);
+    return res;
 #else
     return store_instance_attr_lock_held(obj, values, name, value);
 #endif

```
